import os
import stat
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def count_readable(names: list[str]) -> int:
    """Count the names that refer to readable files inside NOTES_DIR.

    NOTES_DIR ("notes") is relative to the current working directory. Each
    name is a path relative to it, so subdirectory names like "sub/b.txt"
    are valid. A name counts if it is a regular file that can be opened and
    read. An empty file counts. Missing files, directories and unreadable
    files do not count, and each occurrence in `names` is counted
    separately.

    Names are untrusted. Any name that would reach outside NOTES_DIR does
    not count, and the file is not read. This covers "..", absolute paths,
    symlinks that point outside, sibling directories with a shared prefix
    (such as "notes2"), and malformed names such as ones containing NUL
    bytes. The function never raises for a bad name.
    """
    try:
        base = Path(NOTES_DIR).resolve()
    except (OSError, RuntimeError):
        return 0
    nonblock = getattr(os, "O_NONBLOCK", 0)
    count = 0
    for name in names:
        if "\x00" in name:
            continue
        try:
            candidate = (base / name).resolve()
            if candidate == base or not candidate.is_relative_to(base):
                continue
            fd = os.open(candidate, os.O_RDONLY | nonblock)
            try:
                if not stat.S_ISREG(os.fstat(fd).st_mode):
                    continue
                os.read(fd, 1)
            finally:
                os.close(fd)
        except (OSError, ValueError, RuntimeError):
            continue
        count += 1
    return count


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha")
    (notes / "sub" / "b.txt").write_text("beta")
    (notes / "empty.txt").write_text("")
    (tmp_path / "secret.txt").write_text("secret")
    (tmp_path / "notes2").mkdir()
    (tmp_path / "notes2" / "x.txt").write_text("x")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_basic_and_subdirectory(workdir: Path) -> None:
    assert count_readable(["a.txt"]) == 1
    assert count_readable(["a.txt", "sub/b.txt"]) == 2


def test_empty_list(workdir: Path) -> None:
    assert count_readable([]) == 0


def test_empty_file_counts(workdir: Path) -> None:
    assert count_readable(["empty.txt"]) == 1


def test_missing_not_counted(workdir: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "nodir/a.txt"]) == 0
    assert count_readable(["a.txt", "nope.txt"]) == 1


def test_directories_not_counted(workdir: Path) -> None:
    assert count_readable(["sub", "sub/", ".", "", "./"]) == 0


def test_duplicates_counted_each(workdir: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "sub/b.txt"]) == 3


def test_parent_traversal_rejected(workdir: Path) -> None:
    assert (workdir / "secret.txt").exists()
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["../../secret.txt"]) == 0
    assert count_readable(["./../secret.txt"]) == 0
    assert count_readable(["sub/../../notes2/x.txt"]) == 0


def test_sibling_prefix_directory_rejected(workdir: Path) -> None:
    assert count_readable(["../notes2/x.txt"]) == 0


def test_absolute_path_outside_rejected(workdir: Path) -> None:
    assert count_readable([str(workdir / "secret.txt")]) == 0
    assert count_readable(["/etc/passwd"]) == 0
    assert count_readable(["//etc/passwd"]) == 0


def test_traversal_mixed_with_valid(workdir: Path) -> None:
    names = ["a.txt", "../secret.txt", "sub/b.txt", "/etc/passwd"]
    assert count_readable(names) == 2


def test_symlink_file_escaping_rejected(workdir: Path) -> None:
    link = workdir / "notes" / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert count_readable(["link.txt"]) == 0


def test_symlink_dir_escaping_rejected(workdir: Path) -> None:
    link = workdir / "notes" / "out"
    try:
        link.symlink_to(workdir / "notes2", target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unavailable")
    assert count_readable(["out/x.txt"]) == 0


def test_symlink_inside_notes_allowed(workdir: Path) -> None:
    link = workdir / "notes" / "alias.txt"
    try:
        link.symlink_to(workdir / "notes" / "a.txt")
    except OSError:
        pytest.skip("symlinks unavailable")
    assert count_readable(["alias.txt"]) == 1


def test_nul_byte_does_not_raise(workdir: Path) -> None:
    assert count_readable(["a.txt\x00", "a\x00.txt", "\x00"]) == 0
    assert count_readable(["a.txt\x00../secret.txt"]) == 0


def test_backslash_names_not_escaping(workdir: Path) -> None:
    assert count_readable(["..\\secret.txt", "sub\\..\\..\\secret.txt"]) == 0


def test_very_long_name_does_not_raise(workdir: Path) -> None:
    assert count_readable(["a" * 10000, "sub/" + "b" * 10000]) == 0


def test_unreadable_file_not_counted(workdir: Path) -> None:
    import os

    target = workdir / "notes" / "locked.txt"
    target.write_text("hidden")
    target.chmod(0)
    try:
        if os.access(target, os.R_OK):
            pytest.skip("permissions not enforced (running as root?)")
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        target.chmod(0o644)


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt", "../x"]) == 0

